TEST_TIMEOUT_SECONDS = 300  # a mutant that makes the code loop forever must end the run, not hang it; the hang is reported as a failure of the test file


def run_tests(tree, test_file):
    command = [sys.executable, "-m", "unittest", "discover", "-s", "tests", "-p", test_file]
    process = subprocess.Popen(command, cwd=tree, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace",
                               env={**__import__("os").environ, "PYTHONDONTWRITEBYTECODE": "1", "PYTHONIOENCODING": "utf-8"},
                               start_new_session=sys.platform != "win32")
    try:
        stdout, stderr = process.communicate(timeout=TEST_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        if sys.platform == "win32":
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(process.pid)], capture_output=True)  # the test's own child processes die with it
        else:
            __import__("os").killpg(process.pid, 9)
        process.communicate()
        return 1, f"TIMED OUT after {TEST_TIMEOUT_SECONDS} s: the code under test hung"
    result = subprocess.CompletedProcess(command, process.returncode, stdout, stderr)
    lines = [line for line in (result.stderr or result.stdout).splitlines() if line.strip()]
    if result.returncode != 0:  # name the failing tests and their error lines so a flaky baseline can be diagnosed, not just counted
        for line in lines:
            if line.startswith(("ERROR:", "FAIL:")) or "Error" in line.split(":")[0][-12:]:
                print("   ", line[:300])
    return result.returncode, lines[-1] if lines else ""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--only", nargs="*", help="run only these mutation IDs")
    args = parser.parse_args()
    caught = missed = stale = 0
    with tempfile.TemporaryDirectory(prefix="gamearts-mutation-") as scratch:
        tree = Path(scratch) / "repo"
        tree.mkdir()
        for name in COPIED:
            source = ROOT / name
            if source.is_dir():
                shutil.copytree(source, tree / name, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
            elif source.is_file():
                shutil.copy2(source, tree / name)
        for master in ROOT.glob("GAME_ARTS_MASTER_STANDARD*.md"):
            shutil.copy2(master, tree / master.name)
        selected = [m for m in MUTATIONS if not args.only or m[0] in args.only]
        files = sorted({m[5] for m in selected})  # a focused run checks only the test files its mutations need, never the whole suite
        for test_file in files:
            code, last = run_tests(tree, test_file)
            print(f"BASELINE {test_file}: {'ok' if code == 0 else 'FAILS BEFORE ANY MUTATION'} ({last})")
            if code != 0:
                return 1
        for ident, finding, rel, old, new, test_file in selected:
            target = tree / rel
            original = target.read_text(encoding="utf-8", newline="")
            probe = old.replace("\n", "\r\n") if "\r\n" in original and "\r\n" not in old else old
            if original.count(probe) != 1:
                print(f"{ident} STALE   {finding}: anchor found {original.count(probe)} times in {rel}")
                stale += 1
                continue
            replacement = new.replace("\n", "\r\n") if probe != old else new
            target.write_text(original.replace(probe, replacement), encoding="utf-8", newline="")
            try:
                code, last = run_tests(tree, test_file)
            finally:
                target.write_text(original, encoding="utf-8", newline="")
            if code == 0:
                print(f"{ident} MISSED  {finding}: {test_file} still passes with the old behavior restored")
                missed += 1
            else:
                print(f"{ident} caught  {finding}: {test_file} fails ({last})")
                caught += 1
    print(f"\ncaught {caught}, missed {missed}, stale {stale} of {caught + missed + stale}")
    return 0 if not missed and not stale else 1


if __name__ == "__main__":
    raise SystemExit(main())
